pub noinline fn cgemv_kernel_4x1_c(n: isize, ap: [*]f32, x: [*]f32, y: [*]f32) void {
    var i: isize = 0;
    var n1: isize = n & -8;
    const n2: isize = n & 4;
    asm volatile (
        \\vzeroupper
        \\        vbroadcastss      (%[x]), %%ymm0
